-- Phase 2 CMS + evidence-based website audit insights.
create table if not exists public.website_cms_drafts(
 slug text primary key check(slug in ('home','about','services','projects','contact','privacy')),
 content jsonb not null default '{}'::jsonb check(jsonb_typeof(content)='object'),
 updated_by uuid references auth.users(id), updated_at timestamptz not null default now());
create table if not exists public.website_cms_versions(
 id uuid primary key default gen_random_uuid(), slug text not null check(slug in ('home','about','services','projects','contact','privacy')),
 version_no int not null, content jsonb not null, published_by uuid references auth.users(id), published_at timestamptz not null default now(),
 unique(slug,version_no));
create table if not exists public.website_cms_published(
 slug text primary key check(slug in ('home','about','services','projects','contact','privacy')),
 version_no int not null, content jsonb not null, published_at timestamptz not null default now());
alter table public.website_cms_drafts enable row level security;alter table public.website_cms_versions enable row level security;alter table public.website_cms_published enable row level security;
revoke all on public.website_cms_drafts,public.website_cms_versions,public.website_cms_published from anon,authenticated;
grant select,insert,update,delete on public.website_cms_drafts to authenticated;
grant select on public.website_cms_versions to authenticated;
grant select on public.website_cms_published to anon,authenticated;
drop policy if exists cms_admin_drafts on public.website_cms_drafts;create policy cms_admin_drafts on public.website_cms_drafts for all to authenticated using(private.is_karma_admin()) with check(private.is_karma_admin());
drop policy if exists cms_admin_versions on public.website_cms_versions;create policy cms_admin_versions on public.website_cms_versions for select to authenticated using(private.is_karma_admin());
drop policy if exists cms_public_read_published on public.website_cms_published;create policy cms_public_read_published on public.website_cms_published for select to anon,authenticated using(true);
create or replace function public.cms_save_draft(p_slug text,p_content jsonb) returns void language plpgsql security definer set search_path=public,private as $$ begin if not private.is_karma_admin() then raise exception 'Access denied';end if;if p_slug not in('home','about','services','projects','contact','privacy') then raise exception 'Invalid page';end if;if jsonb_typeof(p_content)<>'object' or coalesce(length(p_content->>'title'),0)>180 or coalesce(length(p_content->>'intro'),0)>5000 or jsonb_typeof(coalesce(p_content->'sections','[]'::jsonb))<>'array' or jsonb_array_length(coalesce(p_content->'sections','[]'::jsonb))>30 then raise exception 'Invalid CMS content';end if;insert into public.website_cms_drafts(slug,content,updated_by,updated_at) values(p_slug,p_content,auth.uid(),now()) on conflict(slug) do update set content=excluded.content,updated_by=excluded.updated_by,updated_at=now();end $$;
create or replace function public.cms_publish_page(p_slug text) returns int language plpgsql security definer set search_path=public,private as $$ declare c jsonb;v int;begin if not private.is_karma_admin() then raise exception 'Access denied';end if;select content into c from public.website_cms_drafts where slug=p_slug;if c is null then raise exception 'Draft not found';end if;select coalesce(max(version_no),0)+1 into v from public.website_cms_versions where slug=p_slug;insert into public.website_cms_versions(slug,version_no,content,published_by) values(p_slug,v,c,auth.uid());insert into public.website_cms_published(slug,version_no,content,published_at) values(p_slug,v,c,now()) on conflict(slug) do update set version_no=excluded.version_no,content=excluded.content,published_at=now();return v;end $$;
create or replace function public.cms_restore_version(p_slug text,p_version int) returns void language plpgsql security definer set search_path=public,private as $$ declare c jsonb;begin if not private.is_karma_admin() then raise exception 'Access denied';end if;select content into c from public.website_cms_versions where slug=p_slug and version_no=p_version;if c is null then raise exception 'Version not found';end if;insert into public.website_cms_drafts(slug,content,updated_by,updated_at) values(p_slug,c,auth.uid(),now()) on conflict(slug) do update set content=excluded.content,updated_by=excluded.updated_by,updated_at=now();end $$;
revoke all on function public.cms_save_draft(text,jsonb),public.cms_publish_page(text),public.cms_restore_version(text,int) from public,anon;grant execute on function public.cms_save_draft(text,jsonb),public.cms_publish_page(text),public.cms_restore_version(text,int) to authenticated;
create table if not exists public.website_audit_insights(id uuid primary key default gen_random_uuid(),page_path text not null,rule_key text not null,fingerprint text not null unique,summary text not null,evidence jsonb not null,period_start date not null,period_end date not null,status text not null default 'open' check(status in('open','dismissed','resolved')),created_at timestamptz not null default now());
alter table public.website_audit_insights enable row level security;revoke all on public.website_audit_insights from anon,authenticated;grant select on public.website_audit_insights to authenticated;
drop policy if exists audit_insights_admin_read on public.website_audit_insights;create policy audit_insights_admin_read on public.website_audit_insights for select to authenticated using(private.is_karma_admin());
create or replace function public.generate_website_audit_insights() returns int language plpgsql security definer set search_path=public,private as $$ declare n int:=0;d date:=current_date-14;begin if not private.is_karma_admin() then raise exception 'Access denied';end if;
insert into public.website_audit_insights(page_path,rule_key,fingerprint,summary,evidence,period_start,period_end)
with ev as(select page_path,count(*) filter(where event_name='page_view') views,count(*) filter(where event_name='click') clicks,count(*) filter(where event_name='page_exit') exits,avg(value) filter(where event_name='page_exit') avg_active_seconds from public.analytics_events where created_at>=d and retention_until>now() group by page_path),candidates as(
select page_path,'low_cta_rate' rule_key,md5(page_path||'|low_cta_rate|'||d::text) fingerprint,'Page has traffic but very few tracked clicks' summary,jsonb_build_object('views',views,'clicks',clicks,'click_rate',round(clicks::numeric/greatest(views,1),4)) evidence from ev where views>=20 and clicks::numeric/views<0.02
union all select page_path,'high_exit_rate',md5(page_path||'|high_exit_rate|'||d::text),'Many page visits ended on this page',jsonb_build_object('views',views,'exits',exits,'exit_rate',round(exits::numeric/greatest(views,1),4)) from ev where views>=20 and exits::numeric/views>=0.65
union all select page_path,'short_active_time',md5(page_path||'|short_active_time|'||d::text),'Recorded active time is unusually short',jsonb_build_object('exit_samples',exits,'avg_active_seconds',round(avg_active_seconds,1)) from ev where exits>=20 and avg_active_seconds<=5)
select page_path,rule_key,fingerprint,summary,evidence,d,current_date from candidates on conflict(fingerprint) do nothing;
get diagnostics n=row_count;return n;end $$;
revoke all on function public.generate_website_audit_insights() from public,anon;grant execute on function public.generate_website_audit_insights() to authenticated;
-- Protect retention from anonymous insert values; server trigger overrides client timestamps/deadlines.
create or replace function public.set_website_analytics_retention() returns trigger language plpgsql set search_path=public as $$ begin new.created_at=now();new.retention_until=now()+interval '90 days';return new;end $$;
drop trigger if exists analytics_retention_server_owned on public.analytics_events;create trigger analytics_retention_server_owned before insert on public.analytics_events for each row execute function public.set_website_analytics_retention();
create or replace function public.set_website_consent_retention() returns trigger language plpgsql set search_path=public as $$ begin new.created_at=now();new.retention_until=now()+interval '180 days';return new;end $$;
drop trigger if exists consent_retention_server_owned on public.website_consent_records;create trigger consent_retention_server_owned before insert on public.website_consent_records for each row execute function public.set_website_consent_retention();
-- Correct role helper use in analytics event policy (private helpers are canonical).
drop policy if exists "Karma admins read analytics events" on public.analytics_events;
create policy "Karma admins read analytics events" on public.analytics_events for select to authenticated using(private.is_karma_admin());
